import {storyFor} from './events.js';
export const KEYS=['德','智','体','美','劳'];
export const RANKS=['二级科员','一级科员','四级主任科员','三级主任科员','二级主任科员','一级主任科员','四级调研员','三级调研员','二级调研员','一级调研员','二级巡视员','一级巡视员'];
export const OFFICES=['科员 · 未任领导','乡科级副职','乡科级正职','县处级副职','县处级正职','厅局级副职','厅局级正职','省部级副职','省部级正职','国家级副职','国家级正职 · 国家主席'];
export const PLACES=[{province:'江岚省',city:'临江市',county:'青禾县',town:'云溪镇'},{province:'海宁省',city:'望海市',county:'清浦县',town:'南亭镇'},{province:'北川省',city:'松原市',county:'平山县',town:'白石镇'}];
export const EDUCATION={preschool:{name:'学前启蒙',end:3,degree:'未毕业'},kindergarten:{name:'幼儿园',end:6,degree:'学前'},primary:{name:'小学',end:12,degree:'小学'},middle:{name:'初中',end:15,degree:'初中'},high:{name:'高中',end:18,degree:'高中'},university:{name:'大学本科',end:22,degree:'本科'},master:{name:'硕士研究生',end:25,degree:'硕士'},phd:{name:'博士研究生',end:29,degree:'博士'},preparation:{name:'社会实践与任职准备',end:18,degree:'初中'},work:{name:'任职',end:Infinity,degree:''}};
export const ACTIVITIES=[{name:'读书明理',icon:'卷',desc:'求知与独立思考',gain:[.3,1,.15,.2,.2]},{name:'身体力行',icon:'行',desc:'运动、休息与康复',gain:[.15,.2,1,.3,.3]},{name:'躬身实践',icon:'耕',desc:'从劳动中认识世界',gain:[.5,.4,.3,.15,1]},{name:'心怀他人',icon:'仁',desc:'倾听与照护他人',gain:[1,.3,.2,.3,.4]},{name:'观物审美',icon:'境',desc:'感受艺术与生活之美',gain:[.3,.4,.2,1,.2]}];
export const age=s=>Math.floor(s.day/365);
export const hintStage=s=>age(s)<18?'少年':age(s)<60?'成年':'晚年';
export function create(name='林知远',stats=[20,20,20,20,20],lifespan=90,seed=Date.now()>>>0,place=0){if(!Array.isArray(stats)||stats.length!==5||stats.some(x=>!Number.isInteger(x)||x<5||x>60)||stats.reduce((a,b)=>a+b,0)!==100)throw Error('初始五维每项5–60，总和必须为100');if(!Number.isInteger(lifespan)||lifespan<70||lifespan>110)throw Error('寿命须为70–110岁');if(!PLACES[place])throw Error('请选择出生地');return {version:2,name:String(name).trim().slice(0,20)||'林知远',stats:[...stats],lifespan,seed:seed>>>0,rng:seed>>>0,day:0,merit:0,insight:0,correct:0,decisions:0,mistakes:0,erased:0,logs:[],history:[],milestones:[],pending:false,ended:false,deathReason:'',place,stage:'preschool',degree:'未毕业',educationHistory:[],entryAge:null,service:0,progress:0,retired:false,retirementAge:null,retirementOffice:'',transition:null,illness:0,illnesses:0,xian:0,xianUnlocked:false,xianEarned:0,xianDays:0,lastSignals:[]};}
export function school(s){const p=PLACES[s.place];return ({preschool:p.town+'家庭启蒙',kindergarten:p.town+'中心幼儿园',primary:p.town+'中心小学',middle:p.county+'实验初中',high:p.city+'第一高中',university:p.province+'澄川大学',master:'澄川大学公共治理学院',phd:'澄川国立大学治理研究院',preparation:p.county+'青年实践中心',work:''})[s.stage];}
export function location(s){const p=PLACES[s.place],c=career(s);if(s.stage!=='work')return `${p.province} · ${p.city} · ${school(s)}`;if(s.retired)return `${p.city} · 退休生活`;return c.tier<3?`${p.county} · ${p.town}公共服务中心`:c.tier<5?`${p.city} · ${p.county}行政中心`:c.tier<7?`${p.province} · ${p.city}行政中心`:c.tier<9?`${p.province}省务院`:'澄川首都 · 京川市国家议政院';}
export function degreeRate(s){return ({本科:1.12,硕士:1.24,博士:1.36})[s.degree]||1;}
export function career(s){const p=s.progress||0,tier=Math.min(10,Math.floor((p+1e-9)*10));return {rank:s.stage==='work'?RANKS[Math.min(11,Math.floor((p+1e-9)*11))]:EDUCATION[s.stage]?.name||'学生',office:s.stage==='work'?(s.retired?'已退休 · '+(s.retirementOffice||OFFICES[tier]):OFFICES[tier]):'学生 · '+(EDUCATION[s.stage]?.name||'成长中'),level:s.stage==='work'?Math.max(1,27-Math.floor((p+1e-9)*26)):'—',tier,progress:p};}
export function retirementLimit(s){const t=career(s).tier;return t<=4?60:t<=6?65:t<=8?70:80;}
function log(s,text){s.logs.unshift({day:s.day,text});s.logs=s.logs.slice(0,120);}
function milestone(s,type,text){s.milestones.unshift({day:s.day,type,text});s.lastSignals.push(type);log(s,text);}
function random(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296;}
export function checkXian(s){if(!s.xianUnlocked&&s.stats.every(x=>x>100)){s.xianUnlocked=true;s.xian++;s.xianEarned++;milestone(s,'xian','五维皆破百，仙值觉醒：获得1点，可抹去一次决策失误。');}}
export function eraseMistake(s){if(s.xian<1||s.mistakes<1||s.ended)return false;s.xian--;s.mistakes--;s.erased++;const h=s.history.find(x=>!x.ok&&!x.erased);if(h)h.erased=true;log(s,'消耗1点仙值，抹去一次失误的晋升影响。');return true;}
export function healthRisk(s){return s.stats[2]<25?((25-s.stats[2])/25)*.0012:0;}
export function advance(s,days,activity=0){if(s.pending||s.transition||s.ended)return 0;if(![1,7,30,365].includes(days)||!ACTIVITIES[activity])throw Error('无效行动');s.lastSignals=[];const n=Math.min(days,365-s.day%365,s.lifespan*365-s.day),q=days===1?1:days===7?.85:days===30?.68:.5;let done=0;for(let d=0;d<n;d++){const a=age(s),rest=activity===1,health=.55+Math.min(200,s.stats[2])/300,practice=.65+Math.min(200,s.stats[4])/350,direction=.75+Math.min(200,s.stats[0])/500;const recovery=s.illness?.55:1;ACTIVITIES[activity].gain.forEach((g,i)=>{const factor=i===2?1:health*practice*direction;s.stats[i]+=g*.035*factor*recovery;});if(a>=40)s.stats[2]=Math.max(1,s.stats[2]-(a>=65?.025:.012));if(s.illness){s.stats[2]=Math.max(1,s.stats[2]-(rest?.005:.025));s.illness=Math.max(0,s.illness-(rest?3:1));}s.day++;done++;s.merit+=q*(.7+s.stats[0]/200+s.stats[1]/250+s.stats[3]/400+s.stats[4]/200);s.insight+=q;if(s.stage==='work'&&!s.retired)s.service+=1/365;checkXian(s);if(s.xianUnlocked){if(s.stats.every(x=>x>100))s.xianDays++;else s.xianDays=0;if(s.xianDays>=365&&s.stats.every(x=>x>100)){s.xianDays=0;s.xian++;s.xianEarned++;milestone(s,'xian','五维圆融满一年，再得1点仙值。');}}const risk=healthRisk(s);if(risk&&random(s)<risk){if(s.illness&&random(s)<Math.min(.35,(25-s.stats[2])/70)){s.ended=true;s.deathReason='低体力下疾病恶化，人生意外终止';s.pending=false;milestone(s,'death',s.deathReason+'。');break;}if(!s.illness){s.illness=30+Math.floor(random(s)*45);s.illnesses++;log(s,'突发疾病，需要休养。选择「身体力行」可加速康复，低体力会增加风险。');}}if(s.ended)break;}
log(s,`${ACTIVITIES[activity].name} · ${done}天，观察汇报 +${(done*q).toFixed(1)}。`);if(!s.ended&&s.day%365===0)s.pending=true;return done;}
export function event(s){const y=age(s),ix=(Math.imul(y+1,2654435761)^s.seed)>>>0;const story=storyFor(s,career(s),ix);const r=(ix>>>8)%3;return {title:story[0],text:story[1],options:[0,1,2].map(i=>story[2][(i+r)%3]),answer:(story[3]-r+3)%3,context:s.retired?'退休生活':s.stage==='work'?career(s).office:EDUCATION[s.stage].name};}
function retire(s){s.retirementOffice=career(s).office;s.retired=true;s.retirementAge=age(s);milestone(s,'retirement',`${age(s)}岁，办理退休，保留${s.retirementOffice}任职记录。`);}
function promote(s){if(s.stage!=='work'||s.retired)return;const before=career(s);if(age(s)>=retirementLimit(s)){retire(s);return;}const target=Math.min(72,Math.floor(s.lifespan*.8)),span=Math.max(10,target-s.entryAge);const penalty=Math.max(0,s.mistakes*.012-(s.day?s.insight/s.day:0)*.005);s.progress=Math.max(s.progress,Math.min(1,s.service/span*degreeRate(s)-penalty));if(s.progress>1-1e-8)s.progress=1;const after=career(s);if(after.office!==before.office||after.rank!==before.rank){milestone(s,'promotion',`任职进阶：${after.rank} · ${after.office}，调任${location(s)}。`);}}
function enroll(s,key){s.stage=key;milestone(s,'school',`入学：${school(s)} · ${EDUCATION[key].name}。`);}
function enterWork(s){s.stage='work';s.entryAge=age(s);milestone(s,'promotion',`${s.entryAge}岁，以${s.degree}学历进入${location(s)}，从二级科员起步。`);}
function educationStep(s){const a=age(s);if(s.stage==='work'||a<EDUCATION[s.stage].end)return;const completed=s.stage;s.educationHistory.push({stage:completed,school:school(s),age:a});s.degree=EDUCATION[completed].degree;if(completed==='preschool'){enroll(s,'kindergarten');return;}if(completed==='kindergarten'){enroll(s,'primary');return;}if(completed==='primary'){enroll(s,'middle');return;}if(completed==='preparation'||completed==='phd'){enterWork(s);return;}const next={middle:'high',high:'university',university:'master',master:'phd'}[completed];s.transition={completed,next};log(s,`${EDUCATION[completed].name}毕业：请自主选择继续升学或进入任职准备。`);}
export function chooseEducation(s,continueStudy){if(!s.transition||s.ended)return false;s.lastSignals=[];const {next}=s.transition;s.transition=null;if(continueStudy)enroll(s,next);else if(age(s)<18)enroll(s,'preparation');else enterWork(s);return true;}
export function decide(s,index){if(!s.pending||s.ended||![0,1,2].includes(index))return null;s.lastSignals=[];const e=event(s),ok=index===e.answer;s.decisions++;if(ok){s.correct++;s.merit+=100;s.stats=s.stats.map(x=>x+.6);}else{s.mistakes++;s.merit+=20;}const ratio=s.insight/Math.max(1,s.day),detail=ratio>.9?'逐日记录完整，获得详尽成长汇报。':ratio>.7?'阶段记录保留主要线索，部分观察在快进中略去。':'本年为简略汇报；逐日游玩可积累更多观察与履历。';const item={age:age(s),ok,title:e.title,choice:e.options[index],report:detail,context:e.context,erased:false};s.history.unshift(item);s.pending=false;log(s,`年度抉择：${ok?'方向正确':'留下失误'}。${detail}`);checkXian(s);promote(s);educationStep(s);if(s.day>=s.lifespan*365){s.ended=true;s.deathReason='寿终';milestone(s,'ending','人生终章：你留下的，是每一天与每一次选择。');}return item;}
export function migrate(raw){const s=structuredClone(raw);if(s?.version===1){const fresh=create(s.name,[20,20,20,20,20],s.lifespan,s.seed);Object.assign(fresh,s,{version:2,rng:s.seed>>>0});fresh.mistakes=s.decisions-s.correct;fresh.stage=age(s)<3?'preschool':age(s)<6?'kindergarten':age(s)<12?'primary':age(s)<15?'middle':age(s)<18?'high':age(s)<22?'university':'work';fresh.degree=age(s)>=22?'本科':age(s)>=18?'高中':'未毕业';if(fresh.stage==='work'){fresh.entryAge=22;fresh.service=age(s)-22;const target=Math.min(72,Math.floor(s.lifespan*.8));fresh.progress=Math.min(1,Math.max(0,(age(s)-22)/(target-22)-fresh.mistakes*.012));if(age(s)>=retirementLimit(fresh)){fresh.retirementOffice=career(fresh).office;fresh.retired=true;fresh.retirementAge=age(s);}}fresh.xianUnlocked=s.stats.every(x=>x>100);fresh.xian=fresh.xianUnlocked?1:0;fresh.xianEarned=fresh.xian;fresh.deathReason=s.ended?'寿终':'';fresh.history=fresh.history.map(h=>({...h,erased:false}));return validate(fresh);}return validate(s);}
export function validate(s){const num=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0;const integer=x=>Number.isSafeInteger(x)&&x>=0;const fail=()=>{throw Error('存档格式无效');};if(!s||s.version!==2||typeof s.name!=='string'||s.name.length>20||!integer(s.seed)||!integer(s.rng)||!Array.isArray(s.stats)||s.stats.length!==5||s.stats.some(x=>!num(x)||x<1)||!integer(s.lifespan)||s.lifespan<70||s.lifespan>110||!integer(s.day)||s.day>s.lifespan*365||!integer(s.place)||!PLACES[s.place]||!Object.hasOwn(EDUCATION,s.stage)||!['未毕业','学前','小学','初中','高中','本科','硕士','博士'].includes(s.degree))fail();for(const k of ['correct','decisions','mistakes','erased','illness','illnesses','xian','xianEarned','xianDays'])if(!integer(s[k]))fail();for(const k of ['merit','insight','service','progress'])if(!num(s[k]))fail();for(const k of ['pending','ended','retired','xianUnlocked'])if(typeof s[k]!=='boolean')fail();if(s.correct+s.mistakes+s.erased!==s.decisions||s.decisions>age(s)||s.insight>s.day+.01||s.progress>1||s.service>s.day/365+.01||s.xian>s.xianEarned||s.xianDays>s.day||typeof s.deathReason!=='string'||typeof s.retirementOffice!=='string'||(s.stage==='work'&&(!integer(s.entryAge)||s.entryAge<18||s.entryAge>age(s)))||(s.retired&&(!integer(s.retirementAge)||s.retirementAge>age(s)))||(!s.ended&&s.pending&&(s.day===0||s.day%365!==0)))fail();if(s.transition&&(!['middle','high','university','master'].includes(s.transition.completed)||s.transition.next!==({middle:'high',high:'university',university:'master',master:'phd'})[s.transition.completed]||s.pending||s.stage!==s.transition.completed))fail();for(const k of ['logs','history','milestones','educationHistory','lastSignals'])if(!Array.isArray(s[k]))fail();if(s.logs.length>120||s.history.length>110||s.milestones.length>1000||s.educationHistory.length>20||s.logs.some(l=>!l||!integer(l.day)||l.day>s.day||typeof l.text!=='string')||s.history.some(h=>!h||!integer(h.age)||h.age>age(s)||typeof h.choice!=='string'||typeof h.report!=='string'||typeof h.ok!=='boolean')||s.milestones.some(m=>!m||!integer(m.day)||typeof m.text!=='string'||typeof m.type!=='string'))fail();return s;}



